@ExactAbstraction.exact_factor_unique : ∀ {A : Type u_1} {X : Type u_2} {Z : Type u_3} (F : A → X → X) (c : X → Z),
  Function.Surjective c →
    ∀ (G H : A → Z → Z), (∀ (a : A) (x : X), c (F a x) = G a (c x)) → (∀ (a : A) (x : X), c (F a x) = H a (c x)) → G = H

@PredictiveState.distinguishable_injective : ∀ {A : Type u_1} {X : Type u_2} {O : Type u_3} {R : Type u_4}
  {I : Type u_5} (T : A → X → X) (p : X → O) (c : X → R) (G : A → R → R) (d : R → O),
  (∀ (x : X), d (c x) = p x) →
    (∀ (a : A) (x : X), c (T a x) = G a (c x)) →
      ∀ (xs : I → X), (∀ (j k : I), j ≠ k → ¬PredictiveState.FutureEq T p (xs j) (xs k)) → Function.Injective (c ∘ xs)

@PredictiveState.distinguishable_card_le : ∀ {A : Type u_1} {X : Type u_2} {O : Type u_3} {R : Type u_4} {I : Type u_5}
  [inst : Fintype I] [inst_1 : Fintype R] (T : A → X → X) (p : X → O) (c : X → R) (G : A → R → R) (d : R → O),
  (∀ (x : X), d (c x) = p x) →
    (∀ (a : A) (x : X), c (T a x) = G a (c x)) →
      ∀ (xs : I → X),
        (∀ (j k : I), j ≠ k → ¬PredictiveState.FutureEq T p (xs j) (xs k)) → Fintype.card I ≤ Fintype.card R

@PredictiveState.restrict_actions : ∀ {A : Type u_1} {X : Type u_2} {O : Type u_3} {B : Type u_4} (T : A → X → X)
  (p : X → O) (includeAction : B → A) {x y : X},
  PredictiveState.FutureEq T p x y → PredictiveState.FutureEq (fun b => T (includeAction b)) p x y

@ControlledMemory.probe_refinement_factor : ∀ {A : Type u_1} {X : Type u_2} {O : Type u_3} {R : Type u_4}
  (T : A → X → X) (p : X → O) (probe : A) (c : X → R) (G : A → R → R) (d : R → O),
  (∀ (x : X), d (c x) = p x) →
    (∀ (a : A) (x : X), c (T a x) = G a (c x)) → ∀ (x : X), (p x, p (T probe x)) = (d (c x), d (G probe (c x)))

@ControlledMemory.memory_required_at_fixed_visible : ∀ {R : Type u_1} (c : ControlledMemory.Cell → R)
  (G : ControlledMemory.Action → R → R) (d : R → Bool),
  (∀ (s : ControlledMemory.Cell), d (c s) = s.visible) →
    (∀ (a : ControlledMemory.Action) (s : ControlledMemory.Cell), c (ControlledMemory.cellStep a s) = G a (c s)) →
      ∀ (v : Bool),
        c { visible := v, memory := false, nuisance := false } ≠ c { visible := v, memory := true, nuisance := false }

@WongPredictiveBridge.extracted_is_compress : ∀ {Node : Type u_1} {Coord : Type u_2} [inst : Fintype Node]
  [inst_1 : LinearOrder Coord] (G : WongGARG.GARG Node Coord) (x : Coord),
  G.ExtractedAt x = AncestryObservation.compress (fun s => s ∈ G.samples) (G.AtLocus x)

